function H(x,y,s){const n=Math.sin(x*127.1+y*311.7+s*74.7)*43758.5453;return n-Math.floor(n)}
function vn(x,y,s){const xi=Math.floor(x),yi=Math.floor(y),xf=x-xi,yf=y-yi,u=xf*xf*(3-2*xf),v=yf*yf*(3-2*yf);return H(xi,yi,s)*(1-u)*(1-v)+H(xi+1,yi,s)*u*(1-v)+H(xi,yi+1,s)*(1-u)*v+H(xi+1,yi+1,s)*u*v}
function fbm(x,y,s){let a=.5,t=0;for(let i=0;i<4;i++){t+=a*vn(x,y,s+i);x=x*2+17;y=y*2+3;a/=2}return t}
